const K = 1432.3944878270581;
const TY = 2043.7236197835327;
const L0 = (-12 * Math.PI) / 180;

/** lon/lat (derece) → harita x/y, sınır çizgileriyle aynı projeksiyon. */
export function project(lon: number, lat: number): [number, number] {
  return [
    K * ((lon * Math.PI) / 180 - L0),
    TY - K * Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360)),
  ];
}
